import pandas as pd
import numpy as np
from io import StringIO
import pandas._libs.lib as lib

# Example 1: CSV with small int (42) followed by large int (2^64)
try:
    csv_data = "col\n42\n18446744073709551616"
    df = pd.read_csv(StringIO(csv_data))
    probe("CSV with small int (42) followed by large int (2^64=18446744073709551616)", {
        "dtype": str(df["col"].dtype),
        "values": df["col"].tolist(),
        "values_repr": repr(df["col"].values)
    })
except Exception as e:
    probe("CSV with small int (42) followed by large int (2^64=18446744073709551616)", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: CSV with small int (42) followed by large float (2^64 + 0.5)
try:
    csv_data = "col\n42\n18446744073709551616.5"
    df = pd.read_csv(StringIO(csv_data))
    probe("CSV with small int (42) followed by large float (2^64 + 0.5 = 18446744073709551616.5)", {
        "dtype": str(df["col"].dtype),
        "values": df["col"].tolist(),
        "values_repr": repr(df["col"].values)
    })
except Exception as e:
    probe("CSV with small int (42) followed by large float (2^64 + 0.5 = 18446744073709551616.5)", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 3: lib.maybe_convert_numeric with value 2^65, coerce_numeric=False
try:
    value = 2 ** 65  # 36893488147419103232
    result = lib.maybe_convert_numeric(np.array([str(value)], dtype=object), set(), False)
    probe("lib.maybe_convert_numeric with value 2^65 (36893488147419103232), coerce_numeric=False", {
        "dtype": str(result.dtype),
        "values": result.tolist(),
        "values_repr": repr(result)
    })
except Exception as e:
    probe("lib.maybe_convert_numeric with value 2^65 (36893488147419103232), coerce_numeric=False", 
