    })
except Exception as e:
    probe("lib.maybe_convert_numeric with value str(2^65), coerce_numeric=False", 
          "__error__: " + type(e).__name__ + ": " + str(e))

# Example 5: lib.maybe_convert_numeric with value -(2^65), coerce_numeric=False
